from lib import *
S = SS('g51')
steps = [
    step("一个定时器的成本:time.NewTimer(1h)+Stop 每次 3 次分配,time.AfterFunc(1h, f)+Stop 每次 1 次分配,time.NewTicker(1h)+Stop 每次 3 次分配,time.Sleep(1µs) 每次 0 次分配。保留 20 万个 NewTimer(1h),堆增加 49.6 MB,平均每个 248 字节(含切片里 8 字节的指针);再保留 20 万个 AfterFunc(1h),堆又增加 27.7 MB,平均每个 139 字节。", t=tl(S(1)), done=lidx(S(1), 'time.Sleep(1µs)', 'AfterFunc(1h, f)+Stop'), mark=lidx(S(1), '248 字节', '139 字节'), b=bars([['NewTimer:每个占堆(字节)', 248, '248'], ['AfterFunc:每个占堆(字节)', 139, '139']], 248, mark=[0, 1]), kv=KV([['NewTimer / NewTicker', '3 次分配'], ['AfterFunc', '1 次分配'], ['Sleep', '0 次分配'], ['内存', 'NewTimer 约 248 字节,AfterFunc 约 139 字节']], ['内存'])),
    step("通道语义:NewTimer(1h) 的 cap(t.C) 和 len(t.C) 都是 0;NewTimer(1ms) 到期 20 ms 后还没人读,len 和 cap 仍是 0。对这个“已到期但没人读”的定时器 Reset(1h) 返回 true,之后非阻塞读 t.C 走了 default,没有旧值;另一个同样状态的定时器 Stop() 返回 true,之后读 t.C 也没有旧值。", t=tl(S(2)), done=lidx(S(2), 'cap(t.C)=0', 'len(t.C)=0'), mark=lidx(S(2), 'Reset(1h) 返回 true', 'Stop() 返回 true', 'Stop 之后读'), kv=KV([['cap / len', '恒为 0'], ['已到期没人读时 Reset / Stop', '都返回 true'], ['之后读 t.C', '没有旧值']], ['已到期没人读时 Reset / Stop'])),
    step("到点之后多久被唤醒(实际耗时 − 请求时长,各 200 次):time.Sleep(10µs):中位 7 µs;100µs:中位 29 µs;1ms:中位 261 µs(203–336);10ms:中位 2030 µs(40–2237)。NewTimer 并 <-t.C:100µs 中位 33 µs;1ms 中位 263 µs。10 ms 的睡眠为什么中位多出整整 2 ms,我没有查。", t=tl(S(3)), done=lidx(S(3), 'Sleep(   10µs)', 'Sleep(  100µs)', 'NewTimer(  100µs)'), mark=lidx(S(3), 'Sleep(    1ms)', 'Sleep(   10ms)', 'NewTimer(    1ms)'), b=bars([['Sleep 10µs:中位超时(µs)', 7, '7'], ['Sleep 100µs', 29, '29'], ['Sleep 1ms', 261, '261'], ['Sleep 10ms', 2030, '2030']], 2030, done=[0, 1], mark=[2, 3]), kv=KV([['Sleep / NewTimer 的差别', '同一时长下中位数几乎相同'], ['10 ms', '中位多出 2030 µs,原因未查']], ['10 ms'])),
    step("已有大量待触发的定时器时,再创建并停止一个新的要多久(每格 20 万次的平均)。AfterFunc 在已有 1000 / 10 万 / 100 万个时:98 / 109 / 195 ns;无人等待的 NewTimer:174 / 215 / 195 ns;有 goroutine 阻塞在 t.C 的 NewTimer:215 / 315 / 112 ns。数字没有随数量单调增长(同一程序第一次运行时这几格在 189–490 ns 之间波动),在这个测法下我分不出 O(log n) 的趋势。", t=tl(S(4)), done=lidx(S(4), 'AfterFunc                          已有    1000 个', 'NewTimer(无人等待)                     已有    1000 个'), mark=lidx(S(4), '已有 1000000 个'), b=bars([['AfterFunc 已有 1000 个(ns)', 98, '98'], ['AfterFunc 已有 100 万个', 195, '195'], ['阻塞型 NewTimer 已有 10 万个', 315, '315'], ['阻塞型 NewTimer 已有 100 万个', 112, '112']], 315, done=[0], mark=[1, 2, 3]), kv=KV([['结论', '每个新定时器创建+停止约 100–300 ns'], ['数量的影响', '本测法下看不出单调增长'], ['限制', '每格只有一次测量,第二次运行结果有波动']], ['限制'])),
    step("运行时源码(runtime/time.go):timers 是每个 P 一个的定时器集合,里面的 heap 按 when 排序(A timers is a per-P set of timers / heap is the set of timers, ordered by heap[i].when)。needsAdd 的判断是 t.state&timerHeaped == 0 && t.when > 0 && (!t.isChan || t.blocked > 0)——也就是说,通道型定时器只有在有 goroutine 阻塞等它(blocked > 0)时才需要放进堆。文档(go doc)写着 Go 1.23 起通道是同步的(容量 0),Stop 之后读 t.C 保证阻塞而不是收到旧值,垃圾回收器可以回收没有引用的定时器,即使它们还没到期或被停止。", t=tl(S(5)), done=lidx(S(5), 'A timers is a per-P set', 'heap is the set of timers'), mark=lidx(S(5), 'needsAdd reports', 'timerHeaped == 0', 'guaranteed to block', 'can recover unreferenced'), kv=KV([['堆', '每个 P 一个,按 when 排序'], ['通道型定时器', 'blocked > 0 才放进堆'], ['Go 1.23 起', '通道容量 0,GC 可回收未引用的定时器']], ['通道型定时器'])),
]
A = mkartg('g51', 51, 'Go,time.Timer,Ticker,定时器,runtime,真实验证,动画演示',
    '在 Go 1.27.1(arm64 macOS)里剖开 time.Timer:NewTimer 每次 3 次分配、约 248 字节,AfterFunc 1 次分配、约 139 字节;通道 cap/len 恒为 0,到期未读时 Reset/Stop 返回 true 且没有旧值;Sleep 与 Timer 的唤醒误差(100µs 中位约 30 µs,1ms 约 260 µs,10ms 约 2 ms);并读源码里每个 P 一个定时器堆、通道型定时器有人阻塞才入堆的判断。',
    '一个 time.Timer 在运行时里是什么?占多少内存、会不会让创建变慢、到点之后多久能醒?这篇用分配计数、通道状态、唤醒误差和大量定时器下的创建时间回答,并读 runtime/time.go 里决定定时器放不放进堆的那一行。',
    [('3 次 / 1 次', 'NewTimer 与 AfterFunc 创建并停止一次的分配次数'), ('248 / 139 字节', '保留 20 万个时,每个 NewTimer 和 AfterFunc 占的堆'), ('0', '通道型定时器 t.C 的 cap 与 len,到期没人读也是 0')],
    [('成本', '<p><code>NewTimer</code> 与 <code>NewTicker</code> 每次分配 3 次,<code>AfterFunc</code> 只要 1 次(它没有通道),<code>time.Sleep</code> 不分配。保留 20 万个时,平均 248 字节与 139 字节;这里的堆数字是 GC 后的 HeapAlloc 差值,包含切片里指针的 8 字节。</p>'),
     ('通道里没有缓冲', '<p>Go 1.23 起定时器通道容量为 0:到期了但没人读时 <code>len</code> 与 <code>cap</code> 都是 0。这时 <code>Reset</code> 与 <code>Stop</code> 仍返回 <code>true</code>(文档:没读过且定时器在运行,Stop 一定返回 true),之后读不到旧值。所以老写法里 Stop 返回 false 就多读一次 <code>t.C</code> 来排空的做法,在 1.23 之后不再需要。</p>'),
     ('唤醒误差', '<p>macOS 上 <code>Sleep(100µs)</code> 中位多睡 29 µs,<code>Sleep(1ms)</code> 多睡约 260 µs,<code>Timer</code> 与 <code>Sleep</code> 几乎一样。<code>Sleep(10ms)</code> 中位多睡约 2 ms,我没有查原因(可能与系统定时器粒度有关,是猜测,没有验证)。需要微秒级精度的程序不能依赖它。</p>'),
     ('定时器多了不一定变慢', '<p>在已有 1000 到 100 万个待触发定时器时再创建并停止一个新的,耗时在 100–300 ns 之间,没有稳定的增长趋势;重复运行时同一格的数字会波动。这个测法只有一次测量每格,我不能据此断言“与数量无关”,只能说本机上没观察到随数量变慢。</p>'),
     ('源码里的两个事实', '<p>一是定时器堆是每个 P 一个(<code>timers</code> 的注释),二是 <code>needsAdd</code> 里 <code>(!t.isChan || t.blocked &gt; 0)</code>:通道型定时器没有 goroutine 阻塞在它上面时不需要放进堆,所以没人等的 <code>NewTimer</code> 不会拖慢运行时,也能被 GC 回收(NewTimer 文档)。</p>')],
    steps,
    [ENV_G + '。分配次数用 testing.AllocsPerRun(1000 次);堆占用 = 创建 20 万个并保留后 runtime.GC() 再读 HeapAlloc 的差;唤醒误差每种 200 次;大量定时器的创建耗时每格一次 20 万次平均,前后两次完整运行的数字不同(文中用第二次,第一次的范围已在步骤里注明);读过的源码:runtime/time.go 的 timers 结构、needsAdd,以及 go doc time.Timer.Stop / time.NewTimer 的文字',
     '没有验证:Linux 上的唤醒误差、10ms 睡眠多出 2 ms 的原因、定时器堆的具体算法(四叉堆等细节没有读)、定时器在多个 P 之间迁移的过程、Ticker 的内部差别(下一篇专门讲泄漏)、大量定时器下 O(log n) 是否真的存在(本测法下看不出)'],
    '定时器的实现')
